    const alCompletenessSheet=XLSX.utils.json_to_sheet(ALABAMA_PACKAGE_RULES.map(rule=>{const filing=rule.system==="20C"?al20cResult.result:alCptResult.result;const presence=alabamaReview.packagePresence[rule.id]??"unknown";return {System:rule.system,"Form / Schedule":rule.form,Name:rule.name,Embedded:rule.embedded?"Yes":"No","Package Evidence":presence,"Dynamic Status":packageStatus(rule,alabamaReview.facts,filing,presence),Reason:rule.reason,"Rule Status":rule.ruleStatus,"Tax Year":2025,Jurisdiction:"Alabama","Source Agency":"Alabama Department of Revenue","Official Source":rule.source,"Last Verified":"2026-09-09"};}));
