    const alGuidanceSheet=XLSX.utils.json_to_sheet(allLines.filter(line=>line.jurisdiction==="AL").map(line=>{const guide=getAlabamaLineGuidance(line);return {Form:line.formNumber,Section:line.sectionName,Line:line.lineNumber,Description:line.description,"Likely Sources":guide.sources.join("; "),"Federal Step":guide.federal,"Alabama Adjustment":guide.adjustment,"Data Lineage":guide.chain,"Tax Year":2025,Jurisdiction:"Alabama","Source Agency":"Alabama Department of Revenue","Last Verified":"2026-09-09"};}));
    const federalPdfAuditSheet=XLSX.utils.json_to_sheet(federalPdfImport.history.flatMap(entry=>entry.mappings.map(mapping=>({"Import ID":entry.id,"PDF File":entry.fileName,"File SHA-256":entry.fileHash,"Imported At":entry.importedAt,"PDF Pages":entry.pageCount,"Searchable Pages":entry.textPageCount,"Detected Forms":entry.detectedForms.join("; "),Form:mapping.formNumber,Section:mapping.sectionName,Line:mapping.lineNumber,Description:mapping.description,"PDF Page":mapping.pageNumber,"Source Text":mapping.rawText,"Extracted Amount":mapping.extractedValue,"Previous CPA Amount":mapping.previousAmount,Overwritten:mapping.overwritten?"Yes":"No","Match Confidence":mapping.confidence,"Confidence Level":mapping.confidenceLabel}))));
    const questionSheet = XLSX.utils.json_to_sheet(questions.map(q => { const line = allLines.find(l => l.lineId === q.lineId); const r = normalizeRecord(calculatedRecords[q.lineId]); return { "Question ID": q.id, Jurisdiction: line?.jurisdiction, Form: line?.formNumber, Line: line?.lineNumber, Topic: q.topic, Question: q.question, Background: q.background, "Intended Recipient":q.intendedRecipient, "CPA Amount": r.cpaAmount, "Internal Amount": r.internalAmount, Difference: difference(r), Priority: q.priority, "CPA Response": q.response, "Internal Conclusion": q.conclusion, "Future Treatment": q.futureTreatment, Status: q.status, Created:q.createdAt, "Last Modified":q.updatedAt }; }));
    const issueSheet = XLSX.utils.json_to_sheet(issueLines.map(line => { const r = normalizeRecord(calculatedRecords[line.lineId]); return { Jurisdiction: line.jurisdiction, Form: line.formNumber, Section: line.sectionName, Line: line.lineNumber, Description: line.description, "CPA Amount": r.cpaAmount, "Internal Review": r.internalAmount, Difference: difference(r), "Issue Type": issueReasons(line).join("; "), Risk: r.risk, Status: statusLabels[r.status] }; }));
    styleSheet(federalReviewSummary,[14,24,18,20,18,22,18,22,24,20,18]); styleSheet(expectedActualSheet,[16,34,44,18,48,12,30,24,12,24,36,42,12,18,48]); styleSheet(crossFormSheet,[16,34,26,36,22,20,36,20,16,18,12,24,40,36,12,18,48]); styleSheet(informationReviewSheet,[34,20,22,42,16,18,12,24,40]); styleSheet(dataChecklistSheet,[34,12,30,30,22,18,34,42]); styleSheet(taxFormInputsSheet,[12,12,26,10,44,18,20,22,22,22,18,40]); styleSheet(dataLineageSheet,[12,24,10,42,28,26,28,16,18,18,18,20,16,20,24,18,14,24,18,40]); styleSheet(missingDataSheet,[12,24,10,42,40,40,40,58,18,24,40]);
    styleSheet(summary, [14, 12, 16, 16, 14, 16]); reviewSheets.forEach(({ sheet }) => styleSheet(sheet, [12, 10, 22, 18, 8, 42])); styleSheet(reconciliation, [48, 14, 10, 10, 16, 18, 16, 36]); styleSheet(tbSheet, [18, 34, 15, 15, 16, 16, 18, 12, 28, 12, 48, 22]); styleSheet(bookTaxSheet, [54, 18]); styleSheet(adjustmentSheet, [34, 16, 14, 16, 16, 48, 22, 24, 36, 14]); styleSheet(controlSheet, [58, 18, 18, 18, 20]); styleSheet(yearComparisonSheet, [12, 10, 28, 10, 48, 12, 18, 12, 18, 18, 18, 18, 18]); styleSheet(knowledgeSheet, [22, 12, 10, 10, 28, 48, 48, 14, 18, 12, 24]); styleSheet(stateScopeSheet, [10, 20, 28, 25, 20, 20, 18, 18, 18, 14, 12, 12, 12, 12, 24, 18, 22, 22, 28, 20, 40, 48]); styleSheet(stateDirectorySheet, [10, 20, 30, 25, 24, 20, 24, 24, 20, 24, 24, 28, 20, 24, 48]); styleSheet(alCompletenessSheet,[10,20,34,10,18,20,50,18,12,14,28,48,16]); styleSheet(alCrossCheckSheet,[54,18,18,18,12,34,44,12,14]); styleSheet(alGuidanceSheet,[12,30,10,46,48,38,46,58,12,14,28,16]); styleSheet(federalPdfAuditSheet,[38,30,68,24,12,16,40,18,28,10,46,12,68,18,20,12,18,16]); styleSheet(questionSheet, [18, 12, 10, 8, 22, 54, 36, 15, 15, 15, 12, 32, 32, 32, 14]); styleSheet(issueSheet, [12, 10, 22, 8, 42, 15, 17, 15, 30, 10, 20]);
    XLSX.utils.book_append_sheet(wb, summary, "Review Summary"); XLSX.utils.book_append_sheet(wb, dataChecklistSheet, "Data Checklist"); XLSX.utils.book_append_sheet(wb, tbSheet, "GL-to-Tax Mapping"); XLSX.utils.book_append_sheet(wb, taxFormInputsSheet, "Tax Form Inputs"); XLSX.utils.book_append_sheet(wb, adjustmentSheet, "Book-to-Tax Adjustments"); XLSX.utils.book_append_sheet(wb, crossFormSheet, "Cross-form Reconciliation"); XLSX.utils.book_append_sheet(wb, dataLineageSheet, "Data Lineage"); XLSX.utils.book_append_sheet(wb, missingDataSheet, "Missing Data"); XLSX.utils.book_append_sheet(wb, issueSheet, "Review Issues"); XLSX.utils.book_append_sheet(wb, questionSheet, "Questions for Tax Firm"); XLSX.utils.book_append_sheet(wb, federalReviewSummary, "Federal Review Summary"); XLSX.utils.book_append_sheet(wb, expectedActualSheet, "Expected vs Actual Forms"); XLSX.utils.book_append_sheet(wb, informationReviewSheet, "Information Return Review"); XLSX.utils.book_append_sheet(wb, stateScopeSheet, "State Filing Scope"); XLSX.utils.book_append_sheet(wb, stateDirectorySheet, "50-State Directory"); XLSX.utils.book_append_sheet(wb, alCompletenessSheet, "AL Form Completeness"); XLSX.utils.book_append_sheet(wb, alCrossCheckSheet, "AL Cross-checks"); XLSX.utils.book_append_sheet(wb, alGuidanceSheet, "AL Data Guidance"); XLSX.utils.book_append_sheet(wb, bookTaxSheet, "Book-to-Tax Bridge"); XLSX.utils.book_append_sheet(wb, controlSheet, "Bridge Controls"); XLSX.utils.book_append_sheet(wb, yearComparisonSheet, "Year-over-Year Review"); XLSX.utils.book_append_sheet(wb, knowledgeSheet, "Review Rules"); reviewSheets.forEach(({ form, sheet }) => XLSX.utils.book_append_sheet(wb, sheet, `${form.jurisdiction} ${form.formNumber} Review`.slice(0, 31))); XLSX.utils.book_append_sheet(wb, reconciliation, "Federal-to-State Bridge");
    XLSX.utils.book_append_sheet(wb, federalPdfAuditSheet, "Federal PDF Import Audit");
    XLSX.writeFile(wb, `${fileSegment(project.company)}_Tax_Return_Review_${project.taxYear}.xlsx`);
